def jump(section,label,cls='navlink'):
 return f'<button class="{cls}" onclick="closeMenu();parent.show(\'inicio\',\'{section}\')">{label}</button>'
for key in pages:
 menu='<button class="menutoggle" aria-label="Abrir menu" aria-haspopup="dialog" aria-controls="mobile-navigation" aria-expanded="false" onclick="openMenu()"><span>Menu</span>'+icon('menu')+'</button><dialog id="mobile-navigation" class="menudialog" aria-labelledby="menu-title"><div class="menutop"><span id="menu-title">Explorar</span><button class="menuclose" aria-label="Fechar menu" onclick="closeMenu()">Fechar '+icon('close')+'</button></div><nav class="panelnav" aria-label="Navegação mobile">'
 for n,p,t in [('01','inicio','Início'),('02','projetos','Projetos'),('03','sobre','Sobre mim'),('04','stack','Minha stack'),('05','historia','Minha história'),('06','contato','Contato')]:
  label=f'<span>{n}</span>{t}{icon("arrow-up-right")}'
  if p in ('sobre','stack'): menu+=jump(p,label,'panelitem')
  else: menu+=f'<button class="panelitem" '+('aria-current="page" ' if p==key else '')+f'onclick="closeMenu();parent.show(\'{p}\')">{label}</button>'
 menu+='</nav><div class="menucontact"><span>VAMOS CONVERSAR</span><a href="https://wa.me/5521974885166" target="_blank" rel="noopener">WhatsApp '+icon('external-link')+'</a><a href="tel:+5521974885166">(21) 97488-5166</a><a href="mailto:igorviniciusf10@gmail.com">igorviniciusf10@gmail.com</a></div></dialog>'
 pages[key]=re.sub(r'<details class="mobilemenu">.*?</details>',menu,pages[key],flags=re.S)
 pages[key]=pages[key].replace('<nav aria-label="Navegação principal">','<nav aria-label="Navegação principal">'+jump('sobre','Sobre mim')+jump('stack','Stack'))
 pages[key]=pages[key].replace('<span>Portfólio / 2026</span>','<a href="https://wa.me/5521974885166" target="_blank" rel="noopener">WhatsApp · (21) 97488-5166</a>')

